var n=`0972-doenjang-jjigae`;var t=`world-0972`;var s=`KR`;var a=`east-asia`;var o=4;var g=30;var r={en:`Doenjang Jjigae`,ua:`Твенджан ччіге`};var d={en:`Doenjang Jjigae is a South Korea dish made with yellow onion, zucchini, garlic, doenjang. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Твенджан ччіге, страва кухні країни Південна Корея. Основні складники: жовта цибуля, цукіні, часник, денджан. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var h=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,170,`g`],[`zucchini`,270,`g`],[`garlic`,3,`clove`],[`sesame-oil`,25,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 18 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 18 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:18,i:[[`doenjang`,95,`g`],[`dashi-stock`,850,`ml`],[`shiitake-mushroom`,200,`g`],[`tofu-firm`,350,`g`],[`serrano-pepper`,2,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,55,`g`]]}];var l={slug:n,id:t,country:`KR`,region:a,servings:4,minutes:30,title:r,text:d,steps:h};export{s as country,l as default,t as id,g as minutes,a as region,o as servings,n as slug,h as steps,d as text,r as title};